// Oeste Tooltip — Topanga theme (v0.4.7).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/src/index.js
// Docs: https://oeste.hiddeninwest.com/#/components/tooltip
import React from "react";

export function Tooltip({ children, content, side = "top" }) {
  const [open, setOpen] = React.useState(false);
  const id = React.useId();
  return (
    <span className="relative inline-block"
      onMouseEnter={() => setOpen(true)} onMouseLeave={() => setOpen(false)}>
      {React.cloneElement(React.Children.only(children), {
        "aria-describedby": id,
        onFocus: () => setOpen(true),
        onBlur: () => setOpen(false),
        onKeyDown: (e) => { if (e.key === "Escape") setOpen(false); },
      })}
      {open && (
        <span role="tooltip" id={id}
          className={`absolute left-1/2 z-10 -translate-x-1/2 whitespace-nowrap rounded-md bg-[#1c1917] px-3 py-2 text-xs text-[#f6f4f1] dark:bg-[#f5f3ef] dark:text-[#121110] ${side === "top" ? "bottom-full mb-2" : "top-full mt-2"}`}>
          {content}
        </span>
      )}
    </span>
  );
}
